/**
 * Converts Markdown to PDF, DOCX, or raw MD, or bundles a full
 * ApplicationKit into a ZIP archive.
 *
 * - **pdf** — returns `application/pdf`
 * - **docx** — returns `application/vnd.openxmlformats-officedocument.wordprocessingml.document`
 * - **md** — returns `text/markdown`
 * - **zip** — requires `kit` field; returns `application/zip` with all four documents
 * @summary Export a document or full kit
 */
export const exportDocumentBodyFormatDefault = `md`;

export const ExportDocumentBody = zod.object({
  "format": zod.enum(['pdf', 'docx', 'md', 'zip']).default(exportDocumentBodyFormatDefault),
  "markdown": zod.string().optional().describe('Source Markdown (required for pdf, docx, md formats)'),
  "filename": zod.string().optional().describe('Base filename without extension'),
  "title": zod.string().optional().describe('Document title embedded in PDF\/DOCX metadata'),
  "kit": zod.object({
  "meta": zod.object({
  "targetTitle": zod.string(),
  "company": zod.string(),
  "leadExperiences": zod.array(zod.string()),
  "rationale": zod.string(),
  "sourcesUsed": zod.array(zod.string())
}),
  "resumeMarkdown": zod.string(),
  "coverLetterMarkdown": zod.string(),
  "alignmentNotesMarkdown": zod.string(),
  "starPrepMarkdown": zod.string()
}).optional().describe('Full kit object (required for zip format)')
})

export const ExportDocumentResponse = zod.unknown()


/**
 * Runs a small sample document through each export format (MD, PDF, DOCX, ZIP) and checks the output bytes and magic bytes. Use in dev to verify the Puppeteer and docx pipelines are healthy.
 * @summary Export pipeline smoke test
 */
export const ExportSmokeResponse = zod.object({
  "ok": zod.boolean(),
  "results": zod.record(zod.string(), zod.object({
  "ok": zod.boolean().optional(),
  "bytes": zod.number().optional(),
  "error": zod.string().optional()
}))
})


